contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint priorDeposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (priorDeposit) + (0)); require(priorDeposit <= 1000000000000000000000000000000);
        require(priorDeposit >= 0);
        require(address(this).balance >= priorDeposit);
        c.deposit{value: priorDeposit}(); if (__ESBMC_reverted()) return;
        uint balBeforeZero = address(c).balance;
        c.deposit{value: 0}(); if (__ESBMC_reverted()) return;
        assert(address(c).balance == balBeforeZero);
    }
    receive() external payable {}
}

