// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 priorDeposit) internal {
        priorDeposit = bound(priorDeposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(priorDeposit >= 0);
        vm.assume(address(this).balance >= priorDeposit);
        try c.deposit{value: priorDeposit}() {} catch { return; }
        uint balBeforeZero = address(c).balance;
        try c.deposit{value: 0}() {} catch { return; }
        assertTrue(address(c).balance == balBeforeZero);
    }

    function testFuzz_run(uint256 priorDeposit) public {
        _run(priorDeposit);
    }

    receive() external payable {}
}
